_PLAN_NS = {}
exec(compile('"""top-RE plan layer: desired content per tile by day (DSM/MMPQ family, research/re_findings.md + re_production.md).\ndesired(obs, player) -> dict {(x, y): role}; role in CROPS (\'WHEAT\',\'MELON\',\'STRAWBERRY\',\'CARROT\',\'TOMATO\') or\n\'PASTURE:COW\', \'PASTURE:SHEEP\', \'COOP:GOOSE\', or None (leave / harvest out). Coordinates are engine (x, y); tiles[y][x].\nAlso: targets(obs, player) -> macro targets for the market layer (hands, land timing, herd)."""\nHALF = 5\ndef quad_tiles(q):\n    xs = range(0, 5) if q[1] == "W" else range(5, 10); ys = range(0, 5) if q[0] == "N" else range(5, 10)\n    return [(x, y) for y in ys for x in xs]\ndef _dist_shed(t):  # Manhattan distance to nearest shed-access tile\n    return min(abs(t[0] - a) + abs(t[1] - b) for a, b in ((4, 4), (5, 4), (4, 5), (5, 5)))\ndef _by_shed(tiles): return sorted(tiles, key=lambda t: (_dist_shed(t), t[1], t[0]))\n\n# ---- static layout (tiles closest to the shed host animals: daily FEED/CARE/HARVEST trips are shortest) ----\nNW = _by_shed(quad_tiles("NW")); NE = _by_shed(quad_tiles("NE")); SW = _by_shed(quad_tiles("SW")); SE = _by_shed(quad_tiles("SE"))\nLAYOUT = {\n    # NW: 5 pastures (2 cows, 3 sheep) at d0; 8 melon (d0-2, exits d10-12 -> wheat); 12 wheat opening -> strawberry from d3\n    "NW_PASTURE": NW[:5], "NW_MELON": NW[5:13], "NW_OPEN": NW[13:25],\n    # NE (land #2 ~d6): 6 pastures (cows/sheep), 11 strawberry, 8 wheat\n    "NE_PASTURE": NE[:6], "NE_STRAW": NE[6:17], "NE_WHEAT": NE[17:25],\n    # SW (land #3 ~d8): 7 coops (geese) nearest the shed, 18 wheat (own feed + sales)\n    "SW_COOP": SW[:7], "SW_WHEAT": SW[7:25],\n}\nNW_ANIMALS = ["PASTURE:COW", "PASTURE:COW", "PASTURE:SHEEP", "PASTURE:SHEEP", "PASTURE:SHEEP"]\nNE_ANIMALS = ["PASTURE:COW", "PASTURE:COW", "PASTURE:COW", "PASTURE:COW", "PASTURE:SHEEP", "PASTURE:SHEEP"]\n\ndef desired(obs, player):\n    day = int(obs["day"]); farm = obs["farms"][player]; quads = set(farm.get("unlocked_quadrants") or ["NW"]); want = {}\n    for t, a in zip(LAYOUT["NW_PASTURE"], NW_ANIMALS): want[t] = a\n    for t in LAYOUT["NW_MELON"]: want[t] = "MELON" if day <= 2 else ("WHEAT" if day <= 25 else "CARROT")\n    for t in LAYOUT["NW_OPEN"]: want[t] = "WHEAT" if day <= 2 else ("STRAWBERRY" if day <= 22 else "CARROT")\n    if "NE" in quads:\n        for t, a in zip(LAYOUT["NE_PASTURE"], NE_ANIMALS): want[t] = a\n        for t in LAYOUT["NE_STRAW"]: want[t] = "STRAWBERRY" if day <= 22 else "CARROT"\n        for t in LAYOUT["NE_WHEAT"]: want[t] = "WHEAT" if day <= 26 else "CARROT"\n    if "SW" in quads:\n        for t in LAYOUT["SW_COOP"]: want[t] = "COOP:GOOSE"\n        for t in LAYOUT["SW_WHEAT"]: want[t] = "WHEAT" if day <= 26 else "CARROT"\n    if day >= 28:  # no new planting in the last 2 days: keep standing crops, plant nothing new\n        want = {t: r for t, r in want.items() if ":" in r}\n    return want\n\nHANDS_BY_DAY = [5, 5, 5, 6, 6, 7, 9, 9, 10, 10, 11]  # day index -> hands target; 11 from d10 (DSM/MMPQ medians)\ndef targets(obs, player):\n    day = int(obs["day"])\n    return {"hands": HANDS_BY_DAY[min(day, len(HANDS_BY_DAY) - 1)] if day < 29 else 8,\n            "land_step": {2: 147, 3: 196},  # quads after purchase -> earliest step (DSM/MMPQ median order steps)\n            "wheat_reserve_per_animal": 2}\n', 'plan.py', 'exec'), _PLAN_NS)
plan_desired = _PLAN_NS['desired']
plan_targets = _PLAN_NS['targets']

_MARKET_NS = {}
exec(compile('"""top-RE market layer: HIRE / BUY_LAND / BUY_SEED / BUY_ANIMAL / BUY_PRODUCT WHEAT / SELL, max 10 orders per turn.\norders(obs, player, want, tg) -> list of market orders. Cash priority: land > hires > animals > seeds > feed; sales first."""\nSEED = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}\nANIMAL = {"GOOSE": 300, "COW": 400, "SHEEP": 500}\nLAND = [1000, 2000, 4000]\nBASE = {"WHEAT": 25, "CARROT": 35, "TOMATO": 60, "STRAWBERRY": 120, "MELON": 250, "EGG": 50, "MILK": 160, "WOOL": 200, "FERTILIZER": 100}\nSTEEP = {"STRAWBERRY", "MELON", "MILK", "WOOL"}  # price falls fast with supply: meter these out\ndef fib_cost(n):  # cost of the (n+1)-th hire today\n    a, b = 1, 1\n    for _ in range(n): a, b = b, a + b\n    return a\ndef orders(obs, player, want, tg):\n    farm = obs["farms"][player]; priv = obs.get("private") or {}; shed = dict(priv.get("shed") or {}); seeds = dict(priv.get("seeds") or {})\n    step = int(obs.get("step", 0)); day = int(obs["day"]); hour = int(obs.get("hour", step % 24)); money = float(farm["money"])\n    prices = obs["market"]["prices"]; out = []\n    carried = {}\n    for inv in priv.get("inventories") or []:\n        for k, v in inv.items(): carried[k] = carried.get(k, 0) + v\n    animals = 0; empty_struct = {"COOP": 0, "PASTURE": 0}; tiles = farm["tiles"]\n    for row in tiles:\n        for t in row:\n            if isinstance(t, dict) and t.get("kind") in ("COOP", "PASTURE"):\n                if t.get("animal"): animals += 1\n                else: empty_struct[t["kind"]] += 1\n    last = step >= 715\n    # --- SELL (revenue first). Keep feed wheat; meter steep items unless late game.\n    planned_animals = sum(1 for r in want.values() if ":" in r)\n    feed_need = max(animals, min(planned_animals, animals + 3)) * tg["wheat_reserve_per_animal"]\n    for item in ("MELON", "STRAWBERRY", "MILK", "WOOL", "EGG", "CARROT", "TOMATO", "WHEAT", "FERTILIZER"):\n        have = shed.get(item, 0)\n        if item == "WHEAT": have -= feed_need\n        if item == "FERTILIZER": have -= 4\n        if have <= 0 or len(out) >= 6: continue\n        if item in STEEP and not last and day < 28:\n            if prices[item] < 0.4 * BASE[item] and have < 25: continue   # deep glut: wait for town consumption\n            have = min(have, 15)\n        out.append(["SELL", item, int(have)]); money += have * prices[item] * 0.9\n    # --- LAND\n    nq = len(farm.get("unlocked_quadrants") or ["NW"])\n    if nq < 3:\n        nxt = nq + 1; st = tg["land_step"].get(nxt)\n        if st is not None and step >= st and money >= LAND[nq - 1] + 150:\n            out.append(["BUY_LAND"]); money -= LAND[nq - 1]\n    # --- HIRE up to today\'s target\n    need_h = tg["hands"] - len(farm.get("hands") or [])\n    h = int(farm.get("hires_today", 0))\n    while need_h > 0 and len(out) < 10 and money >= fib_cost(h) + 50:\n        out.append(["HIRE"]); money -= fib_cost(h); h += 1; need_h -= 1\n    # --- SEEDS for empty desired crop tiles\n    need_s = {}\n    for (x, y), role in want.items():\n        if ":" in role: continue\n        if tiles[y][x] is None: need_s[role] = need_s.get(role, 0) + 1\n    for c in ("MELON", "WHEAT", "STRAWBERRY", "CARROT", "TOMATO"):\n        n = need_s.get(c, 0) - seeds.get(c, 0)\n        if n > 0 and len(out) < 10:\n            k = min(n, int(max(0, money - 30) // SEED[c]))\n            if k > 0: out.append(["BUY_SEED", c, k]); money -= k * SEED[c]\n    # --- ANIMALS for empty structures (+ planned structure tiles still empty ground)\n    need_a = {"GOOSE": 0, "COW": 0, "SHEEP": 0}\n    for (x, y), role in want.items():\n        if ":" not in role: continue\n        kind, a = role.split(":"); t = tiles[y][x]\n        if t is None or (isinstance(t, dict) and t.get("kind") == kind and not t.get("animal")): need_a[a] += 1\n    for a in ("COW", "SHEEP", "GOOSE"):\n        n = need_a[a] - shed.get(a, 0) - carried.get(a, 0)\n        if shed.get(a, 0) + carried.get(a, 0) >= 2: n = 0   # animals waiting for placement: don\'t buy more\n        while n > 0 and money >= ANIMAL[a] + 100 and len(out) < 10:\n            k = min(n, int((money - 100) // ANIMAL[a]))\n            if k <= 0: break\n            out.append(["BUY_ANIMAL", a, k]); money -= k * ANIMAL[a]; n -= k\n    # --- FEED wheat top-up\n    wheat = shed.get("WHEAT", 0) + carried.get("WHEAT", 0)\n    if wheat < feed_need and len(out) < 10:\n        k = min(feed_need - wheat, int(max(0, money - 30) // max(1, prices["WHEAT"] + 1)))\n        if k > 0: out.append(["BUY_PRODUCT", "WHEAT", k])\n    return out[:10]\n', 'market.py', 'exec'), _MARKET_NS)
market_orders = _MARKET_NS['orders']

_UNITS_NS = {}
exec(compile('"""Minimal greedy unit controller (fallback / smoke test for plan+market). act(obs, plan) -> (farmer, hands)."""\nACCESS = [(4, 4), (5, 4), (4, 5), (5, 5)]\nCROPS = {"WHEAT": (2, 4, False, 6), "CARROT": (2, 3, False, 4), "TOMATO": (8, 8, True, 4), "STRAWBERRY": (10, 10, True, 4), "MELON": (10, 12, False, 6)}\nPRODUCTS = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL", "FERTILIZER")\ndef _step_toward(p, q):\n    if p[0] < q[0]: return ["EAST"]\n    if p[0] > q[0]: return ["WEST"]\n    if p[1] < q[1]: return ["SOUTH"]\n    if p[1] > q[1]: return ["NORTH"]\n    return None\ndef act(obs, plan):\n    p = plan["player"]; farm = obs["farms"][p]; priv = obs.get("private") or {}; day = int(obs["day"]); hour = int(obs.get("hour", 0))\n    tiles = farm["tiles"]; want = plan["want"]; seeds = dict(priv.get("seeds") or {}); shed = dict(priv.get("shed") or {})\n    units = [tuple(farm["farmer"])] + [tuple(h) for h in (farm.get("hands") or [])]\n    invs = list(priv.get("inventories") or [])\n    while len(invs) < len(units): invs.append({})\n    tasks = []  # (value, (x,y), action, needs)\n    for y in range(10):\n        for x in range(10):\n            t = tiles[y][x]; role = want.get((x, y))\n            if t == "LOCKED": continue\n            if t is None:\n                if role and ":" not in role and seeds.get(role, 0) > 0: tasks.append((6, (x, y), ["PLANT", role], None))\n                elif role and ":" in role: tasks.append((5, (x, y), ["BUILD_" + role.split(":")[0]], None))\n                continue\n            k = t.get("kind")\n            if k == "WEED": tasks.append((2, (x, y), ["DIG"], None)); continue\n            if k == "PLANT":\n                fyd, myd, ongoing, mx = CROPS[t["crop"]]; age = day - t["planted_day"]\n                if not t["watered_today"]: tasks.append((9 if t["consecutive_unwatered"] >= 1 else 4, (x, y), ["WATER"], None))\n                if t.get("yield_units", 0) > 0 and (ongoing or age >= myd or t["yield_units"] >= mx): tasks.append((7, (x, y), ["HARVEST"], None))\n                if role and role != t["crop"] and not ongoing and age >= myd and t.get("yield_units", 0) <= 0: tasks.append((1, (x, y), ["DIG"], None))\n                continue\n            if k in ("COOP", "PASTURE"):\n                if t.get("animal"):\n                    if not t.get("fed_today"): tasks.append((10 if t.get("consecutive_unfed", 0) >= 1 else 8, (x, y), ["FEED"], "WHEAT"))\n                    if not t.get("cared_today"): tasks.append((3, (x, y), ["CARE"], None))\n                    if t.get("yield_units", 0) > 0: tasks.append((6, (x, y), ["HARVEST"], None))\n                    if t.get("fertilizer_available"): tasks.append((2, (x, y), ["COLLECT_FERTILIZER"], None))\n                else:\n                    a = (role or ":").split(":")[1]\n                    if a: tasks.append((7, (x, y), ["PLACE", a], a))\n    # zones: split owned tiles into len(units) contiguous chunks (by quadrant, then row) -> each unit prefers its zone\n    owned = [(x, y) for y in range(10) for x in range(10) if tiles[y][x] != "LOCKED"]\n    owned.sort(key=lambda t: (("NW", "NE", "SW", "SE").index(("N" if t[1] < 5 else "S") + ("W" if t[0] < 5 else "E")), t[1], t[0] if t[1] % 2 == 0 else -t[0]))\n    nz = max(1, len(units)); zone = {t: (i * nz) // max(1, len(owned)) for i, t in enumerate(owned)}\n    taken = set(); acts = []\n    for i, u in enumerate(units):\n        inv = invs[i]; carrying = {k: v for k, v in inv.items() if v > 0}\n        prod = sum(v for k, v in carrying.items() if k in PRODUCTS and k != "WHEAT")\n        best = None\n        for val, pos, a, need in tasks:\n            if (pos, a[0]) in taken: continue\n            if need and carrying.get(need, 0) <= 0: continue\n            d = abs(u[0] - pos[0]) + abs(u[1] - pos[1]); score = val / (1 + d)\n            if zone.get(pos, 0) == i % nz: score *= 3.0\n            if best is None or score > best[0]: best = (score, pos, a, d)\n        # shed errands: drop products / fetch wheat or animals\n        acc = min(ACCESS, key=lambda q: abs(u[0] - q[0]) + abs(u[1] - q[1])); dacc = abs(u[0] - acc[0]) + abs(u[1] - acc[1])\n        unfed = sum(1 for _, _, a, n in tasks if n == "WHEAT")\n        need_wheat = unfed > 0 and carrying.get("WHEAT", 0) <= 0 and shed.get("WHEAT", 0) > 0 and i < 1 + max(2, unfed // 3)\n        need_animal = next((n for _, _, a, n in tasks if a[0] == "PLACE" and shed.get(n, 0) > 0 and carrying.get(n, 0) <= 0), None)\n        errand = None\n        at_shed = dacc == 0\n        if at_shed and prod > 0: errand = ["DROP"]\n        elif at_shed and carrying.get("WHEAT", 0) < 2 and shed.get("WHEAT", 0) >= 4 and unfed > 0:\n            k = min(shed["WHEAT"], 4); errand = ["PICKUP", "WHEAT", k]; shed["WHEAT"] -= k\n        elif at_shed and need_animal: errand = ["PICKUP", need_animal, 1]; shed[need_animal] -= 1\n        elif prod >= 8 or (hour >= 22 and prod > 0): errand = ["DROP"]\n        elif need_wheat: k = min(shed.get("WHEAT", 0), max(4, unfed)); errand = ["PICKUP", "WHEAT", k]; shed["WHEAT"] = shed.get("WHEAT", 0) - k\n        elif need_animal: errand = ["PICKUP", need_animal, 1]; shed[need_animal] -= 1\n        if errand:\n            acts.append(errand if dacc == 0 else _step_toward(u, acc)); continue\n        if best is None: acts.append(["PASS"]); continue\n        _, pos, a, d = best; taken.add((pos, a[0]))\n        acts.append(a if d == 0 else _step_toward(u, pos))\n    return acts[0], acts[1:]\n', 'units.py', 'exec'), _UNITS_NS)
units_act = _UNITS_NS['act']

"""top-RE agent entry (bundled into a single main.py by bundle.py).
Pipeline per turn: plan.desired -> market.orders -> units.act."""
def _unit_plan(obs, player, want):
    tiles = obs["farms"][player]["tiles"]; seeds = (obs.get("private") or {}).get("seeds") or {}
    plant, build, place, dig = {}, {}, {}, {}
    for (x, y), role in want.items():
        t = tiles[y][x]
        if ":" in role:
            kind, animal = role.split(":")
            if t is None: build[(x, y)] = kind
            elif isinstance(t, dict) and t.get("kind") == kind and not t.get("animal"): place[(x, y)] = animal
            elif isinstance(t, dict) and t.get("kind") == "WEED": dig[(x, y)] = 1
        else:
            if t is None and seeds.get(role, 0) > 0: plant[(x, y)] = role
            elif isinstance(t, dict) and t.get("kind") == "WEED": dig[(x, y)] = 1
    for y, row in enumerate(tiles):
        for x, t in enumerate(row):
            if isinstance(t, dict) and t.get("kind") == "WEED": dig[(x, y)] = 1
    return {"plant_targets": plant, "build_targets": build, "place_targets": place, "dig_targets": dig, "load_size": 6, "player": player, "want": want}

def agent(obs, config=None):
    player = int(obs["player"])
    want = plan_desired(obs, player)
    tg = plan_targets(obs, player)
    try:
        market = market_orders(obs, player, want, tg)
    except Exception:
        market = []
    try:
        farmer, hands = units_act(obs, _unit_plan(obs, player, want))
    except Exception:
        farmer, hands = ["PASS"], [["PASS"] for _ in obs["farms"][player].get("hands") or []]
    return {"farmer": farmer, "hands": hands, "market": market}
